# longest common substring between seq and comp (inverted repeat), and seq vs seq (direct repeat) using suffix approach (small: 3000 -> use simple DP with arrays)
def lcs(a,b,minlen=20):
    n=len(a); m=len(b)
    # rolling arrays
    prev=[0]*(m+1); best=[]
    for i in range(1,n+1):
        cur=[0]*(m+1)
        for j in range(1,m+1):
            if a[i-1]==b[j-1]:
                cur[j]=prev[j-1]+1
                if cur[j]>=minlen:
                    best.append((cur[j],i-cur[j],j-cur[j]))
        prev=cur
    best.sort(reverse=True)
    # dedupe
    out=[]
    for l,ia,ib in best:
        if not any(l<=lo and ia>=oa and ia+l<=oa+lo for lo,oa,ob in out):
            out.append((l,ia,ib))
    return out[:10]
